import React, { useState, useEffect } from 'react';
import JobAdminPage from './pages/JobAdminPage';
import LoginPage from './pages/LoginPage';
import RecruiterDashboard from './pages/RecruiterDashboard';

function App() {
  const [user, setUser] = useState(null);

  useEffect(() => {
    const savedUser = localStorage.getItem('user');
    if (savedUser) {
      const parsedUser = JSON.parse(savedUser);
      console.log('📦 LOADED USER FROM STORAGE:', parsedUser); // ADD THIS
      setUser(parsedUser);
    }
  }, []);

  const handleLogin = (userData) => {
    console.log('🔐 USER LOGGED IN:', userData); // ADD THIS
    setUser(userData);
  };

  const handleLogout = () => {
    localStorage.removeItem('user');
    setUser(null);
  };

  if (loading) {
    return (
      <div style={{ 
        display: 'flex', 
        alignItems: 'center', 
        justifyContent: 'center', 
        minHeight: '100vh',
        background: '#0f0f10',
        color: '#ffffff'
      }}>
        Loading...
      </div>
    );
  }
return (
    <div>
      {!user ? (
        <LoginPage onLogin={handleLogin} />
      ) : user.role === 'hr' ? (
        <JobAdminPage user={user} onLogout={handleLogout} />
      ) : (
        <RecruiterDashboard user={user} onLogout={handleLogout} />
      )}
    </div>
  );

  // Not logged in - show login page
  if (!user) {
    return <LoginPage onLogin={handleLogin} />;
  }

  // HR logged in - show full admin dashboard
  if (user.role === 'hr') {
    return <JobAdminPage user={user} onLogout={handleLogout} />;
  }

  // Recruiter logged in - show limited dashboard
  if (user.role === 'recruiter') {
    return <RecruiterDashboard user={user} onLogout={handleLogout} />;
  }

  return null;
}

export default App;
